<script setup lang="ts">
import { computed,onMounted,reactive,ref } from "vue";import { Pige360SessionClient,type ApiProblem } from "@pige360/auth";type Row=Record<string,any>;const api=new Pige360SessionClient();const ready=ref(false),auth=ref(false),busy=ref(false),error=ref(""),notice=ref(""),email=ref(""),password=ref("");const tenants=ref<Row[]>([]),selectedTenant=ref("");const kit=ref<Row>({payload:{},assets:[],versions:[]});const preview=ref<Row|null>(null);const form=reactive<Row>({legal_name:"",trade_name:"",short_name:"",app_display_name:"",primary_domain:"",primary_color:"#006D77",secondary_color:"#0D1B2A",accent_color:"#F59E0B",typography_family:"Inter",co_branding_policy:"disabled"});const plane=computed(()=>api.claims()?.plane||"tenant");const target=computed(()=>plane.value==='platform'&&selectedTenant.value?`/platform/tenants/${selectedTenant.value}/branding`:"/branding");
function msg(e:unknown){const p=(e as Error&{problem?:ApiProblem})?.problem;return p?.detail||(e instanceof Error?e.message:"Erro inesperado");}function fill(){Object.assign(form,{legal_name:"",trade_name:"",short_name:"",app_display_name:"",primary_domain:"",primary_color:"#006D77",secondary_color:"#0D1B2A",accent_color:"#F59E0B",typography_family:"Inter",co_branding_policy:"disabled"},kit.value.payload||{});document.documentElement.style.setProperty('--brand-primary',form.primary_color);document.documentElement.style.setProperty('--brand-secondary',form.secondary_color);}
async function load(){if(plane.value==='platform'){tenants.value=(await api.request<Row>("/platform/tenants")).items||[];if(!selectedTenant.value)selectedTenant.value=tenants.value[0]?.id||"";if(!selectedTenant.value)return;}kit.value=await api.request<Row>(target.value);fill();}
async function boot(){try{await api.initialize();auth.value=!!api.tokens;if(auth.value)await load();}catch(e){error.value=msg(e);}finally{ready.value=true;}}async function login(){try{await api.login(email.value,password.value);auth.value=true;await load();}catch(e){error.value=msg(e);}}async function logout(){await api.logout();auth.value=false;}async function changeTenant(){preview.value=null;await load();}
async function runPreview(){try{preview.value=await api.request<Row>(`${target.value}/preview`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({changes:{...form}})});}catch(e){error.value=msg(e);}}
async function publish(){busy.value=true;try{const result=await api.request<Row>(`${target.value}/publish`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({payload:{...form},reason:"Publicação aprovada no Branding Studio"})});notice.value=`Branding v${result.version} publicado.`;await load();}catch(e){error.value=msg(e);}finally{busy.value=false;}}
async function rollback(version:number){if(!confirm(`Restaurar a versão ${version}?`))return;try{await api.request(`${target.value}/rollback`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({version,reason:"Rollback solicitado no Branding Studio"})});notice.value=`Versão ${version} restaurada.`;await load();}catch(e){error.value=msg(e);}}
async function upload(event:Event,category:string){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;try{const b64=await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(r.error);r.onload=()=>resolve(String(r.result).split(',')[1]||'');r.readAsDataURL(file);});await api.request(`${target.value}/assets`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({category,filename:file.name,mime_type:file.type||'application/octet-stream',content_base64:b64})});notice.value="Ativo enviado e verificado por SHA-256.";await load();}catch(e){error.value=msg(e);}finally{busy.value=false;}}onMounted(boot);
</script>
<template><div v-if="!ready" class="center">Inicializando Branding Studio…</div><div v-else-if="!auth" class="login-page"><form class="login-card" @submit.prevent="login"><div class="mark">◐</div><span class="eyebrow">Branding Studio</span><h1>Gestão de identidade</h1><label>E-mail<input v-model="email" type="email" required></label><label>Senha<input v-model="password" type="password" required></label><p v-if="error" class="flash error">{{error}}</p><button class="primary">Entrar</button></form></div><div v-else class="mobile-shell"><header><div class="brand"><div class="mark">◐</div><div><strong>{{plane==='platform'?'PIGE360':form.short_name||form.trade_name||'Branding'}}</strong><small>Branding Studio</small></div></div><button class="ghost" @click="logout">Sair</button></header><main><div v-if="error" class="flash error">{{error}}</div><div v-if="notice" class="flash success">{{notice}}</div><section v-if="plane==='platform'" class="panel"><label>Tenant<select v-model="selectedTenant" @change="changeTenant"><option v-for="t in tenants" :key="t.id" :value="t.id">{{t.trade_name}} · {{t.code}}</option></select></label></section><section class="studio-grid"><form class="panel form" @submit.prevent="runPreview"><div class="section-title"><h2>Identidade</h2><span>{{kit.state}} · v{{kit.active_version||0}}</span></div><label>Razão social<input v-model="form.legal_name" required></label><label>Nome da escola<input v-model="form.trade_name" required></label><label>Nome curto<input v-model="form.short_name" required></label><label>Nome dos aplicativos<input v-model="form.app_display_name" required></label><label>Domínio principal<input v-model="form.primary_domain" placeholder="www.escola.com.br" required></label><div class="colors"><label>Primária<input v-model="form.primary_color" type="color"></label><label>Secundária<input v-model="form.secondary_color" type="color"></label><label>Destaque<input v-model="form.accent_color" type="color"></label></div><label>Tipografia<input v-model="form.typography_family"></label><label>Co-branding<select v-model="form.co_branding_policy"><option value="disabled">Desativado</option><option value="optional">Opcional</option><option value="required">Obrigatório</option></select></label><div class="actions"><button class="ghost-dark" type="submit">Validar e visualizar</button><button class="primary" type="button" :disabled="busy" @click="publish">Publicar versão</button></div></form><div class="panel preview" :style="{'--preview-primary':form.primary_color,'--preview-secondary':form.secondary_color,'--preview-accent':form.accent_color}"><span class="eyebrow">Preview</span><div class="preview-header"><div class="preview-logo">{{(form.short_name||'E').slice(0,2).toUpperCase()}}</div><strong>{{form.trade_name||'Nome da instituição'}}</strong></div><div class="preview-hero"><h2>{{form.app_display_name||form.trade_name}}</h2><p>Interface white-label utilizando os tokens publicados.</p><button>Continuar</button></div><div v-if="preview?.contrast" class="contrast"><div v-for="(c,key) in preview.contrast" :key="key"><strong>{{key}}</strong><small>branco {{c.on_white.ratio}} · {{c.on_white.passes_aa?'AA':'falha AA'}}</small><small>escuro {{c.on_dark.ratio}} · {{c.on_dark.passes_aa?'AA':'falha AA'}}</small></div></div></div></section><section class="grid two"><div class="panel"><h2>Ativos oficiais</h2><label class="upload">Logo principal<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" @change="upload($event,'logo_primary_light')"></label><label class="upload">Ícone do aplicativo<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" @change="upload($event,'app_icon_source')"></label><label class="upload">Splash<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" @change="upload($event,'splash_source')"></label><div class="list-row" v-for="a in kit.assets" :key="a.id"><div><strong>{{a.category}}</strong><span>{{a.original_filename}}</span></div><small>{{a.sha256?.slice(0,12)}}…</small></div></div><div class="panel"><h2>Versões</h2><div class="list-row" v-for="v in kit.versions" :key="v.id"><div><strong>v{{v.version}} · {{v.state}}</strong><span>{{v.sha256?.slice(0,16)}}…</span></div><button v-if="v.version!==kit.active_version" class="small" @click="rollback(v.version)">Restaurar</button></div></div></section></main></div></template>
